import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aLine[i]);
        }

        List<Integer> leftSums = new ArrayList<>();
        List<Integer> rightSums = new ArrayList<>();
        int half = n / 2;

        calcLeft(0, 0, a, m, half, leftSums);
        calcRight(half, 0, a, n, m, rightSums);

        Set<Integer> uniqueLeftSet = new HashSet<>(leftSums);
        List<Integer> uniqueLeft = new ArrayList<>(uniqueLeftSet);
        Collections.sort(uniqueLeft);

        int maxTotal = 0;
        for (int val : rightSums) {
            int target = m - val;
            int pos = Collections.binarySearch(uniqueLeft, target);
            if (pos < 0) {
                pos = -pos - 1;
            }
            if (pos > 0) {
                int candidate = uniqueLeft.get(pos - 1) + val;
                if (candidate > maxTotal) {
                    maxTotal = candidate;
                }
            }
        }
        System.out.println(maxTotal);
    }

    private static void calcLeft(int i, int total, int[] a, int m, int half, List<Integer> leftSums) {
        if (i == half) {
            leftSums.add(total);
        } else {
            calcLeft(i + 1, (total + a[i]) % m, a, m, half, leftSums);
            calcLeft(i + 1, total, a, m, half, leftSums);
        }
    }

    private static void calcRight(int i, int total, int[] a, int n, int m, List<Integer> rightSums) {
        if (i == n) {
            rightSums.add(total);
        } else {
            calcRight(i + 1, (total + a[i]) % m, a, n, m, rightSums);
            calcRight(i + 1, total, a, n, m, rightSums);
        }
    }
}
